"""Golden values generated by unmodified MATLAB files executed in Octave."""
from pathlib import Path
import numpy as np
from numpy.testing import assert_allclose
from scipy.io import loadmat
from hsbsm import Grid, default_parameters
from hsbsm.physics import penman_monteith, canopy_step, infiltration_step, soil_step
from hsbsm.aquifer import fixed_step

GOLD = loadmat(Path(__file__).parent/"fixtures"/"matlab_reference.mat", squeeze_me=True)


def test_pm_and_canopy_match_matlab():
    p = default_parameters()
    f = dict(Temp_C=20., Pres_kPa=101.325, Wind_ms=2., VapP_kPa=1.5, SRad_Wm2=200.,
             LRad_Wm2=350., Albd=0.2, LAI=2., P=1e-6, fv=0.6)
    pm = penman_monteith(f, p)
    assert_allclose([pm[k] for k in ("wet", "dry", "bare", "ra", "rn")], GOLD["pm"], rtol=1e-12)
    can = canopy_step(f["P"], pm["wet"], f["fv"], f["LAI"], 0.0005, p["Veg"], 3600)
    assert_allclose(can, GOLD["canopy"], rtol=1e-12, atol=1e-15)


def test_infiltration_matches_matlab():
    p = default_parameters()
    inf, rex, cum, dry, capacity = infiltration_step(np.array([1e-5, 1e-7, 0]),
        np.array([0, 0.02, 0.1]), np.array([0, 0, 3]), np.array([0.2, 0.3, 0.38]), p, 3600)
    assert_allclose(np.column_stack((inf, rex, cum, dry, capacity)), GOLD["infiltration"], atol=1e-14, rtol=1e-12)


def test_unconstrained_soil_exchange_matches_matlab():
    p = default_parameters()
    s = soil_step(np.array([1e-7, 2e-7]), 1e-8, 2e-9, np.array([0.30, 0.32]),
                  np.array([0.29, 0.31]), np.zeros(2), np.zeros(2), p["Soil"], 60)
    actual = np.column_stack([s[k] for k in ("theta_rz", "theta_tz", "transpiration",
                                             "soil_evaporation", "rz_to_tz", "tz_to_aq")])
    assert_allclose(actual, GOLD["soil"], atol=1e-14, rtol=1e-11)


def test_nonuniform_aquifer_matches_matlab_over_ten_steps():
    g = Grid([5, 17, 35, 60], [8, 7, 5, 3])
    aq = dict(k=1e-4, f=0.2, D=1)
    num = default_parameters()["Num"]
    num["picard_tol"] = 1e-11
    s = 0.2*g.w*np.array([0.1, 0.2, 0.15, 0.1])
    history, flow, overflow = [], [], []
    for _ in range(10):
        s, q, of, residual, converged, _, _ = fixed_step(g, s, np.full(4, 1e-7), aq, 0.1, 60, num)
        assert converged
        history.append(s)
        flow.append(-q)
        overflow.append(of.sum())
    assert_allclose(history, GOLD["aq_s"], rtol=1e-11, atol=1e-12)
    assert_allclose(flow, GOLD["aq_q"], rtol=1e-11, atol=1e-14)
    assert_allclose(overflow, GOLD["aq_over"], atol=1e-14)
